// Turns the two probes into one plain answer, so a failed setup says why.
const health = $('Health (no key needed)').first().json;
const roster = $('Roster (key required)').first().json;

const reachable = health && health.ok === true;
const authorised = roster && Array.isArray(roster.drones);

let verdict;
if (!reachable) {
  verdict = 'CANNOT REACH THE MOD. Check that the Minecraft server is running, that droneApi '
          + 'points at it, and — on n8n Cloud — that your tunnel is up.';
} else if (!authorised) {
  verdict = 'REACHED THE MOD BUT WAS REJECTED. Attach the "Firekeep Drone API" header-auth '
          + 'credential (X-API-Key = the apiKey from config/firekeep-drones.json) to the roster node.';
} else if (roster.count === 0) {
  verdict = 'WORKING, but there are no drones yet. Spawn one: /drone spawn ~ ~5 ~ drone_01';
} else {
  verdict = `WORKING. ${roster.count} drone(s): ` + roster.drones.map(d => `${d.id} (${d.status})`).join(', ');
}

return [{ json: {
  verdict,
  reachable,
  authorised,
  perception_radius: health && health.perception_radius,
  webhook_configured: health && health.webhook_configured,
  webhook_online: health && health.webhook_online,
  drones: roster && roster.drones,
} }];
